import numpy as np, copy
from reference import Task
from scipy.sparse import linalg as spla

def solver_ok(ncv,mult, seeds=100):
    task=Task();
    for seed in range(seeds):
        prob=task.generate_problem(300, random_seed=seed)
        A=prob['matrix']; k=prob['k']; N=A.shape[0]
        vals, vecs = spla.eigs(A,k=k,v0=np.ones(N),ncv=ncv,maxiter=N*mult)
        pairs=sorted(zip(vals,vecs.T), key=lambda p:-abs(p[0]))
        sol=[p[1] for p in pairs]
        if not task.is_solution(prob, sol):
            return False, seed
    return True, None

for ncv in [40,50,60,70,80]:
    for mult in [100,120,150,200]:
        ok,bad=solver_ok(ncv,mult,seeds=30)
        print(ncv,mult,ok)
